import "@krpadesigns/portfolio-design-system/styles.css";
import { ResponsiveTable } from "@krpadesigns/portfolio-design-system";

const columns = [
  { key: "criterion", label: "Criterion" },
  { key: "evidence", label: "Evidence" },
  { key: "status", label: "Status" },
];

const rows = [
  {
    key: "accessibility",
    cells: [
      "Accessibility compliance",
      "WCAG 2.1 AA audit passed; keyboard navigation verified across all interactive components",
      "Met",
    ],
  },
  {
    key: "responsive",
    cells: [
      "Responsive layout",
      "Tested at 1440 px, 768 px, and 390 px viewports; horizontal overflow contained within table region",
      "Met",
    ],
  },
  {
    key: "type-safety",
    cells: [
      "TypeScript type safety",
      "Strict mode enabled; zero type errors on tsc --noEmit across consumer and design-system package",
      "Met",
    ],
  },
];

export function App() {
  return (
    <main style={{ padding: "2rem", maxWidth: "900px", margin: "0 auto" }}>
      <h1 style={{ marginBottom: "1.5rem" }}>Enterprise Evaluation Criteria</h1>
      <ResponsiveTable
        ariaLabel="Evaluation criteria comparison: criterion, evidence, and status"
        columns={columns}
        rows={rows}
        firstColumnIsRowHeader={true}
      />
    </main>
  );
}
